<body>
  <div id="root"></div>
  <script type="text/babel">
    function Stopwatch() {
      const [seconds, setSeconds] = React.useState(0);
      const [running, setRunning] = React.useState(false);

      React.useEffect(() => {
        if (!running) return;
        const id = setInterval(() => setSeconds(s => s + 1), 1000);
        return () => clearInterval(id);
      }, [running]);

      const min = Math.floor(seconds / 60);
      const sec = String(seconds % 60).padStart(2, '0');

      return (
        <div style={{ fontFamily: 'sans-serif', textAlign: 'center', marginTop: 40 }}>
          <h1>⏱️ {min}:{sec}</h1>
          <button onClick={() => setRunning(!running)}>{running ? 'პაუზა' : 'დაწყება'}</button>
          <button onClick={() => { setRunning(false); setSeconds(0); }}>თავიდან</button>
        </div>
      );
    }

    ReactDOM.createRoot(document.getElementById('root')).render(<Stopwatch />);
  </script>
</body>
