        Scanner in = new Scanner(System.in);

        for (int i = 0; i < subjects.length; i++) {
            System.out.print(subjects[i] + " grade (1-10): ");
            grades[i] = in.nextInt();
        }

        int sum = 0, best = 0;
        for (int i = 0; i < grades.length; i++) {
            sum += grades[i];
            if (grades[i] > grades[best]) best = i;
        }
        double average = (double) sum / grades.length;

        System.out.printf("Average: %.2f%n", average);
        System.out.println("Best subject: " + subjects[best]);
        System.out.println(average >= 9 ? "Excellent! 🏆" : average >= 7 ? "Good! 👍" : "A bit more practice 💪");
    }
}

